import React from 'react'
import { connect } from 'react-redux'
import { Form, Row, Col, Input, Button, Select } from 'antd'
import PropTypes from 'prop-types'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'
import customerAction from '../../redux/customer/actions'
import { ChangeNumberStyle } from './changeNumber.style'
import { PhoneNumberPrefix } from '../../../helpers/constant'

const FormItem = Form.Item
const { Option } = Select
const { resetStateCustomer, putEditContact } = customerAction
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class EditNumber extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      time: {},
      seconds: 180
    }
    this.timer = 0
  }

  componentDidMount () {
    const timeLeftVar = this.secondsToTime(this.state.seconds)
    this.setState({ time: timeLeftVar })
    // if(this.props.newNumberEntered) this.startTimer()
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    if (nextProps.newNumberEntered) this.startTimer()
  }

  startTimer () {
    if (this.timer === 0 && this.state.seconds > 0) {
      this.timer = setInterval(this.countDown, 1000)
    }
  }

  secondsToTime (secs) {
    const hours = Math.floor(secs / (60 * 60))

    const divisorMinutes = secs % (60 * 60)
    const minutes = Math.floor(divisorMinutes / 60)

    const divisorSeconds = divisorMinutes % 60
    const seconds = Math.ceil(divisorSeconds)

    const obj = {
      h: hours,
      m: minutes,
      s: seconds
    }
    return obj
  }

  countDown = () => {
    // Remove one second, set state so a re-render happens.
    const seconds = this.state.seconds - 1
    this.setState({
      time: this.secondsToTime(seconds),
      seconds: seconds
    })

    // Check if we're at zero.
    if (seconds === 0) {
      clearInterval(this.timer)
    }
  }

  onResend = () => {
    this.props.onSend()
  }

  handleCancel = () => {
    this.props.form.resetFields()
    this.props.onClosePopupForm()
    this.resetState()
  }

  handleResendOtp = () => {
    this.props.onResend()
    clearInterval(this.timer)
    this.timer = 0
    this.setState({ seconds: 180 })
  }

  handleSave = (e, submit) => {
    this.props.form.validateFields((err, values) => {
      if (!err) {
        submit
          ? this.props.onSubmit(values)
          : this.props.onSave(values)
      }
    })
  }

  onChange = e => {
    this.setState({
      radioValue: e.target.value
    })
  };

  renderCodeVerificationForm = () => {
    const { form } = this.props
    const { time, seconds } = this.state
    const { getFieldDecorator } = form

    return (
      <ChangeNumberStyle>
        <Form>
          <label>Input Verification Number</label>
          <FormItem>
            {
            getFieldDecorator('otp', {
              rules: [
                {
                  required: true,
                  message: 'Cannot be empty'
                }
              ]
            })(<Input disabled={seconds === 0} />)
          }
          </FormItem>
          <div style={{ color: '#999' }}>
            Verification Code will expire after <span style={{ color: '#000' }}>{time.m} minutes {time.s} seconds</span>
          </div>
        </Form>
        <Row>
          <Col span={12}>
            <Button
              className='button-cancel'
              onClick={this.handleResendOtp}
            >
              Resend
            </Button>
          </Col>
          <Col span={12}>
            <Button onClick={(e) => this.handleSave(e, true)} className='button-save'>
              Submit
            </Button>
          </Col>
        </Row>
      </ChangeNumberStyle>
    )
  }

  renderModalContent = () => {
    const { form, oldPhoneNumber } = this.props
    const { getFieldDecorator } = form
    const { updateMobileNumberStatus } = this.state
    const prefixSelector = getFieldDecorator('prefix', {
      initialValue: '62'
    })(
      <Select>
        {PhoneNumberPrefix.map((prefix, index) => (
          <Option key={index} value={prefix.value}>{prefix.label}</Option>
        ))}
      </Select>
    )

    if (updateMobileNumberStatus === undefined) {
      return (
        <>
          <Form>
            <label>Old Phone Number</label>
            <FormItem>
              {
              getFieldDecorator('old_number', {
                rules: [
                  {
                    required: true,
                    message: 'Cannot be empty'
                  }
                ],
                initialValue: `+${oldPhoneNumber}`
              })(<Input disabled />)
            }
            </FormItem>
            <label>New Phone Number</label>
            <FormItem>
              {
              getFieldDecorator('new_number', {
                rules: [
                  {
                    required: true,
                    message: 'Phone number is not valid',
                    min: 7,
                    max: 17
                  }
                ]
              })(<Input
                addonBefore={prefixSelector}
                 />)
            }
            </FormItem>
          </Form>
          <Row>
            <Col span={12}>
              <Button onClick={this.props.onCancel} className='button-cancel'>
                Cancel
              </Button>
            </Col>
            <Col span={12}>
              <Button onClick={this.handleSave} className='button-save'>
                Save
              </Button>
            </Col>

          </Row>
        </>
      )
    }
  }

  render () {
    const { newNumberEntered } = this.props

    return (
      <>
        {
          newNumberEntered
            ? this.renderCodeVerificationForm()
            : this.renderModalContent()
        }
      </>
    )
  }
}

const WrappedEditNumber = Form.create()(EditNumber)

WrappedEditNumber.propTypes = {
  userProfile: PropTypes.object.isRequired,
  userid: PropTypes.string.isRequired,
  email: PropTypes.string,
  phone: PropTypes.string
}

WrappedEditNumber.defaultProps = {
  userProfile: {}
}

export default connect(
  state => ({
    patchEditContactLoading: state.Loading.PUT_EDIT_CONTACT,
    patchEditContactError: state.Error.PUT_EDIT_CONTACT,
    editContactMessage: state.Customer.editContactMessage
  }),
  {
    resetStateCustomer,
    putEditContact,
    resetLoadingRedux,
    resetErrorRedux
  }
)(WrappedEditNumber)
