import React from 'react'
import { connect } from 'react-redux'
import {
  Row,
  Col,
  Card,
  Form,
  Alert,
  Icon,
  Checkbox,
  Modal,
  Spin
} from 'antd'
import _ from 'lodash/object'
import moment from 'moment'
import QueryString from 'query-string'

import delayActions from '../../redux/customer/actions'
import ClaimActions from '../../redux/claims/actions'
import PolicyActions from '../../../redux/policy/actions'
import { isEmpty } from '../../../helpers/utility'
import TableWrapper from './pagination.style'
import EditPersonalModal from './editPersonalModal'
import EditContactModal from './editContactModal'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'
import { CustomerDetailStyle } from './detail.style'
import QuerySearchBuilder from '../../../helpers/querySearchBuilder'
import PermissionChecker from '../../../components/permissionChecker'
import ChangeNumber from './changeNumber'
import { showNotification } from '../../../components/ShowNotification'
import { get } from 'lodash'

const { getCustomer, getPolicyByCustomer, getClaimByCustomer, resetStateCustomer } = delayActions
const { sendOtp, changeUserPhone } = ClaimActions
const { getInsuranceCountData } = PolicyActions
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class Customer extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      customerData: {},
      loading: false,
      getCustomerMessage: '',
      policyData: [],
      claimData: [],
      offset: 0,
      showEditPersonalModal: false,
      showEditContactModal: false,
      openMobileChangePopup: false,
      internalIds: [],
      newNumberEntered: false,
      values: undefined,
      allPoliciesSelected: false
    }
  }

  componentDidMount = () => {
    const querySearch = QueryString.parse(this.props.location.search)
    const userid = this.props.match.params.user_id
    querySearch.userid = userid
    this.props.resetStateCustomer()
    this.props.getCustomer(userid)
    this.props.getClaimByCustomer({ userid, page_size: 10 })
    this.fetch(querySearch)
    this.props.resetErrorRedux(['SEND_OTP', 'CHANGE_USER_PHONE'])
    this.props.resetLoadingRedux(['SEND_OTP', 'CHANGE_USER_PHONE'])
  };

  UNSAFE_componentWillReceiveProps (nextProps) {
    this.setState({ loading: false })
    if (nextProps.sendOtpStatus && nextProps.sendOtpLoading === false) {
      showNotification(
        nextProps.sendOtpError
          ? 'error'
          : 'success',
        nextProps.sendOtpStatus)
      this.setState({ newNumberEntered: !nextProps.sendOtpError })
    }
    if (nextProps.sendOtpError === false && nextProps.sendOtpLoading === false) {
      this.setState({ newNumberEntered: true })
      this.props.resetErrorRedux(['SEND_OTP'])
      this.props.resetLoadingRedux(['SEND_OTP'])
    }

    if (nextProps.changeNumberStatus && nextProps.changeUserPhoneLoading === false) {
      showNotification(
        nextProps.changeUserPhoneError
          ? 'error'
          : 'success',
        nextProps.changeNumberStatus)
    }
    if (nextProps.changeUserPhoneError === false && nextProps.changeUserPhoneLoading === false) {
      this.setState({ openMobileChangePopup: false, newNumberEntered: false })
      const querySearch = QueryString.parse(this.props.location.search)
      const userid = this.props.match.params.user_id
      querySearch.userid = userid
      this.fetch(querySearch)
      this.props.resetErrorRedux(['CHANGE_USER_PHONE'])
      this.props.resetLoadingRedux(['CHANGE_USER_PHONE'])
    }
  }

  fetch = (params = {}) => {
    const { offset, limit, userid } = params
    const offsetNumber = Number(offset) || 0
    const limitNumber = Number(limit) || 10
    delete params.offset
    delete params.limit

    this.setState({
      limit: limitNumber,
      offset: offsetNumber
    }, () => {
      this.props.getPolicyByCustomer({
        query: {
          limit: limitNumber,
          offset: offsetNumber,
          userid: userid
        }
      })
      this.props.getInsuranceCountData({
        userid: userid
      })
    })
  }

  handleTableChange = (pagination) => {
    const { history, location, match } = this.props
    const { pageSize, current } = pagination
    const offset = pageSize * (current - 1)
    const querySearch = QueryString.parse(location.search)
    const finalFilter = {
      ...querySearch,
      offset,
      limit: pageSize
    }
    const searchQuery = QuerySearchBuilder(finalFilter)

    history.push({ pathname: location.pathname, search: searchQuery })
    this.fetch({
      ...finalFilter,
      offset,
      limit: pageSize,
      userid: match.params.user_id
    })
  }

  handleClaimPaginationChange = (pagination) => {
    const userid = this.props.match.params.user_id
    this.props.getClaimByCustomer({ userid, page_size: 10, page: pagination.current })
  }

  policyDetailPage (id, record) {
    const { push } = this.props.history
    push({
      pathname: `/policy/${id}`,
      state: {
        ApplicationNo: record.ApplicationNo
      }
    })
  }

  claimDetailPage = id => {
    const { history } = this.props
    history.push(`/claims/${id}`)
  }

  showEditPersonalModal = () => {
    this.setState({ showEditPersonalModal: true })
  }

  closeEditPersonalModal = () => {
    this.setState({ showEditPersonalModal: false })
  }

  showEditContactModal = () => {
    this.setState({ showEditContactModal: true })
  }

  closeEditContactModal = () => {
    this.setState({ showEditContactModal: false })
  }

  onChangeCheckbox = (item) => {
    const { internalIds } = this.state
    this.setState({
      internalIds: [
        ...internalIds,
        item
      ]
    })
  }

  handleCheckBoxChange = (e) => {
    const { policyData } = this.props
    if (e.target.checked) {
      let internalIds = []
      policyData.map(item => {
        internalIds = [
          ...internalIds,
          item.InternalID
        ]
        return internalIds
      })
      this.setState({ internalIds, allPoliciesSelected: true })
    } else {
      this.setState({ internalIds: this.state.internalIds, allPoliciesSelected: false })
    }
  }

  handleOk = (values) => {
    if (values) {
      this.setState({ values })
    }

    const data = {
      type: 'phone',
      partner: this.props.customerData.partner,
      phone: values
        ? `${values.prefix}-${values.new_number}`
        : `${this.state.values.prefix}-${this.state.values.new_number}`
    }

    this.props.sendOtp(data)
    this.setState({ openMobileChangePopup: true })
  }

  handleCancel = () => {
    this.setState({ openMobileChangePopup: false, newNumberEntered: false })
  }

  onSubmit = (value) => {
    const { otpData, customerData } = this.props
    const { values, internalIds } = this.state

    if (internalIds.length > 0) {
      const data = {
        operation_id: otpData.operation_id,
        new_phone: `${values.prefix}-${values.new_number}`,
        // old_phone: customerData.phone,
        name: customerData.name,
        email: customerData.email,
        partner: customerData.partner,
        otp: value.otp,
        internal_ids: internalIds
      }

      this.props.changeUserPhone(data)
    } else { showNotification('error', 'Please select policies to continue') }
  }

  renderAddresses = () => {
    const { customerData } = this.props
    if (!!customerData && !isEmpty(customerData) && !!customerData.addresses.length) {
      return (customerData.addresses.map((address, index) => {
        return (
          <Row className='customer-info' key={`address_${index}`}>
            <Col sm={7}>
              Address:
            </Col>
            <Col sm={17}>
              {address.area}
            </Col>
          </Row>
        )
      }))
    } else {
      return (
        <Row className='customer-info'>
          <Col sm={24}>
            No Address Found
          </Col>
        </Row>
      )
    }
  }

  renderBankAccounts = () => {
    const { customerData } = this.props
    if (!!customerData && !isEmpty(customerData) && !!customerData.bank_accounts.length) {
      return (customerData.bank_accounts.map((bank, index) => {
        return (
          <Row key={`bank_${index}`} className='customer-info' type='flex' justify='space-around' align='middle'>
            <Col sm={7}>
              Account<br />
              Number
            </Col>
            <Col sm={17}>
              {bank.account_no}
            </Col>
          </Row>
        )
      }))
    } else {
      return (
        <Row className='customer-info'>
          <Col sm={24}>
            No Bank Account Found
          </Col>
        </Row>
      )
    }
  }

  renderDocuments = () => {
    const { customerData } = this.props
    if (!!customerData && !isEmpty(customerData) && !!customerData.documents.length) {
      return (customerData.documents.map((document, index) => {
        return [
          <Row className='customer-info' key={`document_${index}`}>
            <Col sm={7}>
              Name:
            </Col>
            <Col sm={17}>
              {document.name}
            </Col>
          </Row>,
          <Row className='customer-info' key={`Uploaded_${index}`}>
            <Col sm={7}>
              Uploaded:
            </Col>
            <Col sm={17}>
              {moment(document.created_at, 'YYYY-MM-DD').format('ddd, DD-MM-YYYY')}
            </Col>
          </Row>,
          <Row className='customer-info' key={`Link_${index}`}>
            <Col sm={7}>
              Link:
            </Col>
            <Col sm={17}>
              <a href={document.url}>
                {document.url}
              </a>
            </Col>
          </Row>
        ]
      }))
    } else {
      return (
        <Row className='customer-info'>
          <Col sm={24}>
            No Document Found
          </Col>
        </Row>
      )
    }
  }

  renderCustomerProfile = () => {
    const { customerData = {}, policyMetaData, claimData, permissions, customerDataLoading } = this.props
    const totalRecords = Number((policyMetaData || {}).total_records || 0)
    return (
      <Card loading={customerDataLoading} bordered={false}>
        <Row>
          <Col sm={7}>
            <Icon type='user' className='font-size-75' />
          </Col>
          <Col sm={17}>
            <div className='customer-name'>
              {customerData.name}
            </div>
            <Row>
              <center>
                <Col sm={12}>
                  <Icon type='safety-certificate' />
                  <div>
                    <span className='count'>{totalRecords}</span>
                    Policies
                  </div>
                </Col>
                <Col sm={12}>
                  <Icon type='money-collect' />
                  <div>
                    <span className='count'>{claimData.meta_data && claimData.meta_data.total_records}</span>
                    Claims
                  </div>
                </Col>
              </center>
            </Row>
          </Col>
        </Row>
        <Row className='customer-header-row'>
          <Col sm={20} className='border-bottom-grey'>
            Personal Info
          </Col>
          <PermissionChecker permissionGetter={permissions} permissionSetter='ops.customer_edit_personal_info_360'>
            <Col sm={4} className='border-bottom-grey'>
              <div className='edit-modal-button' onClick={() => this.showEditPersonalModal()}>
                <Icon type='edit' />
              </div>
            </Col>
          </PermissionChecker>
        </Row>
        <Row className='customer-info'>
          <Col sm={7}>
            Gender:
          </Col>
          <Col sm={17}>
            {_.get(customerData, 'profile.gender') || 'No Gender set'}
          </Col>
        </Row>
        <Row className='customer-info'>
          <Col sm={7}>
            Birth date:
          </Col>
          <Col sm={17}>
            {
              _.get(customerData, 'profile.dob')
                ? moment(customerData.profile.dob, 'YYYY/MM/DD').format('DD-MM-YYYY')
                : 'No date of birth'
            }
          </Col>
        </Row>
        <Row className='customer-info' type='flex' justify='space-around' align='middle'>
          <Col sm={7}>
            ID User<br />
            (KTP/SIM)
          </Col>
          <Col sm={17}>
            {(_.get(customerData, 'profile.ktp') || _.get(customerData, 'profile.dl_no') || 'No registered ID')}
          </Col>
        </Row>
        <Row className='customer-header-row'>
          <Col sm={20} className='border-bottom-grey'>
            Contact Info
          </Col>
          {
            !!permissions.includes('ops.customer_edit_contact_info_360') && (
              <Col sm={4} className='border-bottom-grey'>
                <div className='edit-modal-button' onClick={() => this.showEditContactModal()}>
                  <Icon type='edit' />
                </div>
              </Col>
            )
          }
        </Row>
        <Row className='customer-info'>
          <Col sm={7}>
            Email:
          </Col>
          <Col sm={17}>
            {customerData.email}
          </Col>
        </Row>
        <Row className='customer-info' type='flex' justify='space-around' align='middle'>
          <Col sm={7}>
            Phone<br />
            Number
          </Col>
          <Col sm={17}>
            {customerData.phone}
          </Col>
        </Row>
        <Row className='customer-header-row'>
          <Col sm={24} className='border-bottom-grey'>
            Bank Account Info
          </Col>
        </Row>
        {this.renderBankAccounts()}
        <Row className='customer-header-row'>
          <Col sm={24} className='border-bottom-grey'>
            Address Info
          </Col>
        </Row>
        {this.renderAddresses()}
        <Row className='customer-header-row'>
          <Col sm={24} className='border-bottom-grey'>
            Document Info
          </Col>
        </Row>
        {this.renderDocuments()}
        <Row className='customer-header-row'>
          <Col sm={24} className='border-bottom-grey'>
            Account Setting
          </Col>
        </Row>
        <Row className='customer-info'>
          <Col sm={7}>
            Language:
          </Col>
          <Col sm={17}>
            {
              _.get(customerData, 'profile.language_code') === 'ind'
                ? 'Bahasa Indonesia'
                : 'English'
            }
          </Col>
        </Row>
        <Row className='customer-info'>
          <Col sm={7}>
            Currency:
          </Col>
          <Col sm={17}>
            Rupiah
          </Col>
        </Row>
        <Row className='customer-info'>
          <Col sm={7}>
            Timezone
          </Col>
          <Col sm={17}>
            UTC + 7
          </Col>
        </Row>
      </Card>
    )
  }

  renderPolicyTable = () => {
    const { policyData, policyMetaData, policyDataLoading, permissions } = this.props
    const { offset, limit, allPoliciesSelected } = this.state

    const totalRecords = Number((policyMetaData || {}).total_records || 0)
    const columns = [
      {
        key: 'policyNo',
        title: (
          <div className='policy-number'>
            <span>
              Policy no /<br />
              Application No
            </span>
          </div>
        ),
        dataIndex: 'InsurancePolicyNo',
        render: (val, record) => {
          const policyNo = val === 'TEMP' || val === ''
            ? record.ApplicationNo
            : val
          return (
            <span
              onClick={() => this.policyDetailPage(record.InternalID, record)}
              className='policy-detail'
            >
              {policyNo}
            </span>
          )
        },
        sorter: true,
        sortDirections: ['descend']
      }, {
        key: 'productKey',
        title: (
          <div className='policy-number'>
            <span>
              Product id
            </span>
          </div>
        ),
        dataIndex: 'ProductKey',
        sorter: true,
        sortDirections: ['descend']
      }, {
        key: 'policyState',
        title: (
          <div className='policy-number'>
            <span>
              Status
            </span>
          </div>
        ),
        dataIndex: 'PolicyState'
      }, {
        key: 'checkbox',
        title: (
          <div className='policy-checkbox'>
            <PermissionChecker permissionGetter={permissions} permissionSetter='ops.change_user_number'>
              <div onClick={this.handlePolicyCheckBox} className='policy-checkbox-text'>
                Change Mobile Number
              </div>
            </PermissionChecker>
            <div>
              <Checkbox onChange={this.handleCheckBoxChange} />
            </div>
          </div>
        ),
        render: (item) => (
          <div className='text-center'>
            <Checkbox onChange={() => this.onChangeCheckbox(item)} indeterminate={allPoliciesSelected} />
          </div>
        ),
        dataIndex: 'InternalID'
      }
    ]
    return (
      <TableWrapper
        columns={columns}
        rowKey={(_, index) => index}
        loading={policyDataLoading}
        pagination={{
          pageSize: 10,
          total: totalRecords,
          current: (offset / limit) + 1
        }}
        onChange={this.handleTableChange}
        dataSource={policyData}
        className='isoSearchableTable'
      />
    )
  }

  handlePolicyCheckBox = () => {
    if (this.state.internalIds.length > 0) {
      this.setState({ openMobileChangePopup: true, newNumberEntered: false })
    } else {
      showNotification('error', 'Please select Policies to continue')
    }
  }

  renderClaimTable = () => {
    const { claimData = {}, claimDataLoading } = this.props
    const { meta_data: metaData = {} } = claimData
    const columns = [
      {
        key: 'claimNo',
        title: (
          <div className='policy-number'>
            <span>Claim no</span>
          </div>
        ),
        dataIndex: 'claim_no',
        render: (val, record) => {
          return (
            <span
              className='policy-detail'
              onClick={() => this.claimDetailPage(record.claim_id)}
            >
              {val}
            </span>
          )
        },
        sorter: true,
        sortDirections: ['descend']
      }, {
        key: 'productKey',
        title: (
          <div className='policy-number'>
            <span>Product id</span>
          </div>
        ),
        dataIndex: 'product_key',
        sorter: true,
        sortDirections: ['descend']
      }, {
        key: 'status',
        title: (
          <div className='policy-number'>
            <span>Status</span>
          </div>
        ),
        dataIndex: 'status'
      }
    ]
    return (
      <TableWrapper
        columns={columns}
        rowKey={(_, index) => index}
        loading={claimDataLoading}
        dataSource={claimData.data}
        className='isoSearchableTable'
        pagination={{
          pageSize: 10,
          total: metaData.total_records
        }}
        onChange={this.handleClaimPaginationChange}
      />
    )
  }

  render () {
    const { showEditPersonalModal, showEditContactModal, newNumberEntered } = this.state
    const { customerData = {}, getCustomerMessage, changeUserPhoneLoading, sendOtpLoading } = this.props

    return (
      <CustomerDetailStyle>
        <Card bodyStyle={{ padding: 0 }} bordered={false}>
          {getCustomerMessage !== '' && getCustomerMessage !== 'Success' && (<Alert message={getCustomerMessage} type='error' />)}
          <EditPersonalModal
            isOpen={showEditPersonalModal}
            customerProfileData={get(customerData, 'profile')}
            onClosePopupForm={(e) => this.closeEditPersonalModal(e)}
            userid={this.props.match.params.user_id}
          />
          <EditContactModal
            isOpen={showEditContactModal}
            email={get(customerData, 'email')}
            phone={get(customerData, 'phone')}
            onClosePopupForm={e => this.closeEditContactModal(e)}
            userid={this.props.match.params.user_id}
          />
          <Modal
            title='Change Phone Number'
            visible={this.state.openMobileChangePopup}
            onCancel={this.handleCancel}
            footer={null}
          // closable={false}
          >
            <Spin spinning={!!changeUserPhoneLoading || !!sendOtpLoading}>
              <CustomerDetailStyle>
                <ChangeNumber
                  newNumberEntered={newNumberEntered}
                  onCancel={() => this.handleCancel()}
                  onSave={(values) => this.handleOk(values)}
                  onResend={() => this.handleOk()}
                  onSubmit={(value) => this.onSubmit(value)}
                  oldPhoneNumber={customerData.phone}
                />
              </CustomerDetailStyle>
            </Spin>

          </Modal>
          <Row type='flex' justify='center' className='row-min-height'>
            <Col sm={6} className='border-bottom-grey'>
              {this.renderCustomerProfile()}
            </Col>
            <Col sm={9} className='border-bottom-grey'>
              <Row>
                <Col sm={24} className='data-policies'>
                  Data Policies
                </Col>
              </Row>
              {this.renderPolicyTable()}
            </Col>
            <Col sm={9}>
              <Row>
                <Col sm={24} className='data-claims'>
                  Data Claims
                </Col>
              </Row>
              {this.renderClaimTable()}
            </Col>
          </Row>
        </Card>
      </CustomerDetailStyle>
    )
  }
}

const WrappedForm = Form.create({})(Customer)

export default connect(state => ({
  customerData: state.Customer.customerData,
  getCustomerMessage: state.Customer.getCustomerMessage,
  customerDataLoading: state.Loading.GET_CUSTOMER,
  customerDataError: state.Error.GET_CUSTOMER,

  policyData: state.Customer.policyData,
  policyMetaData: state.Policy.metadata,
  policyDataLoading: state.Loading.GET_POLICY_CUSTOMER,
  policyDataError: state.Error.GET_POLICY_CUSTOMER,

  claimData: state.Customer.claimData,
  claimDataLoading: state.Loading.GET_CLAIM_CUSTOMER,
  claimDataError: state.Error.GET_CLAIM_CUSTOMER,

  sendOtpLoading: state.Loading.SEND_OTP,
  sendOtpError: state.Error.SEND_OTP,
  sendOtpStatus: state.Claims.sendOtpStatus,
  otpData: state.Claims.otpData,

  changeUserPhoneLoading: state.Loading.CHANGE_USER_PHONE,
  changeUserPhoneError: state.Error.CHANGE_USER_PHONE,
  changeNumberStatus: state.Claims.changeNumberStatus,
  state
}), {
  getCustomer,
  getPolicyByCustomer,
  getClaimByCustomer,
  resetStateCustomer,
  resetLoadingRedux,
  resetErrorRedux,
  sendOtp,
  changeUserPhone,
  getInsuranceCountData
})(WrappedForm)
