import React from 'react'
import { connect } from 'react-redux'
import { Form, Row, Col, Radio, Input, Button, Modal, DatePicker, notification } from 'antd'
import PropTypes from 'prop-types'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'
import customerAction from '../../redux/customer/actions'
import FailedFetchAlert from '../../../components/failedFetchDataAlert'
import moment from 'moment'
import { get } from 'lodash'

const FormItem = Form.Item
const RadioGroup = Radio.Group

const { resetStateCustomer, patchEditCustomer } = customerAction
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class EditPersonalModal extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      providerListData: [],
      radioValue: ''
    }
    this.initState = this.state
  }

  componentDidMount () {
    this.resetState()
  }

  componentWillReceiveProps (nextProps) {
    if (nextProps.editCustomerMessage === 'Successfully edited' &&
        !nextProps.patchEditCustomerError &&
        !nextProps.patchEditCustomerLoading) {
      this.successEdit()
    }
  }

  successEdit = () => {
    notification['success']({
      message: this.props.editCustomerMessage,
      description: ''
    })
    this.handleCancel()
  }

  resetState = () => {
    this.setState(this.initState)
    this.props.resetStateCustomer(['editCustomerMessage'])
    this.props.resetLoadingRedux(['PATCH_EDIT_CUSTOMER'])
    this.props.resetErrorRedux(['PATCH_EDIT_CUSTOMER'])
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  onSubmit = async e => {
    e.preventDefault()
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const {
      form,
      userid,
      customerProfileData
    } = this.props
    const formValues = form.getFieldsValue()
    let payload = {
      ...formValues,
      userid: userid,
      id: get(customerProfileData, 'id'),
      dob: formValues.dob.format('YYYY-MM-DD')
    }
    this.props.patchEditCustomer(payload)
  }

  handleCancel = () => {
    this.props.form.resetFields()
    this.props.onClosePopupForm()
    this.resetState()
  }

  onChange = e => {
    this.setState({
      radioValue: e.target.value
    })
  };

  render () {
    const { getFieldDecorator } = this.props.form
    const {
      customerProfileData,
      patchEditCustomerLoading,
      patchEditCustomerError,
      editCustomerMessage
    } = this.props
    const dateOfBirth = get(customerProfileData, 'dob', '2000/01/01')
    return (
      <Modal
        title='Edit Customer Personal Info'
        visible={this.props.isOpen}
        onCancel={this.handleCancel}
        footer={null}
        closable
        maskClosable={false} >
        <FailedFetchAlert
          status={'error'}
          isNeedDisplay={patchEditCustomerError}
          message={editCustomerMessage}
        />
        <Form id='personal-form' onSubmit={this.onSubmit} style={{ marginTop: '10px' }}>
          <Row>
            <Col sm={6}>
              Gender:
            </Col>
            <Col sm={18}>
              <FormItem>
                {getFieldDecorator('gender', {
                  initialValue: get(customerProfileData, 'gender', 'male'),
                  rules: [{ required: true, message: 'Please select a gender' }]
                })(
                  <RadioGroup onChange={this.onChange}>
                    <Radio value='male'>
                    Male
                    </Radio>
                    <Radio value='female'>
                    Female
                    </Radio>
                  </RadioGroup>
                )}
              </FormItem>
            </Col>
          </Row>
          <Row>
            <Col sm={6}>
              Birth date:
            </Col>
            <Col sm={18}>
              <FormItem>
                {getFieldDecorator('dob', {
                  initialValue: (moment(dateOfBirth, 'YYYY/MM/DD')),
                  rules: [{ required: true, message: 'Please input a birth date' }]
                })(<DatePicker format={'DD-MM-YYYY'} />)}
              </FormItem>
            </Col>
          </Row>
          <Row>
            <Col sm={6}>
              ID User (KTP):
            </Col>
            <Col sm={18}>
              <FormItem>
                {getFieldDecorator('ktp', {
                  initialValue: get(customerProfileData, 'ktp', ''),
                  rules: [{ required: true, message: 'Please input a KTP number' }]
                })(<Input />)}
              </FormItem>
            </Col>
          </Row>
          <FormItem>
            <center>
              <Button
                className='button'
                key='cancel'
                style={{ marginTop: '20px', marginRight: '20px' }}
                onClick={this.handleCancel}
              >
                Cancel
              </Button>
              <Button
                form='personal-form'
                className='button'
                key='submit'
                type='primary'
                htmlType='submit'
                style={{ marginTop: '20px' }}
                loading={patchEditCustomerLoading}
              >
                Submit
              </Button>
            </center>
          </FormItem>
        </Form>
      </Modal>
    )
  }
}

const WrappedEditPersonalModal = Form.create()(EditPersonalModal)

WrappedEditPersonalModal.propTypes = {
  customerProfileData: PropTypes.object
}

WrappedEditPersonalModal.defaultProps = {
  customerProfileData: {}
}

export default connect(
  state => ({
    patchEditCustomerLoading: state.Loading.PATCH_EDIT_CUSTOMER,
    patchEditCustomerError: state.Error.PATCH_EDIT_CUSTOMER,
    editCustomerMessage: state.Customer.editCustomerMessage
  }),
  {
    resetStateCustomer,
    patchEditCustomer,
    resetLoadingRedux,
    resetErrorRedux
  }
)(WrappedEditPersonalModal)
