import React from 'react'
import { connect } from 'react-redux'
import { Form, Row, Col, Input, Button, Modal, notification } from 'antd'
import PropTypes from 'prop-types'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'
import customerAction from '../../redux/customer/actions'
import FailedFetchAlert from '../../../components/failedFetchDataAlert'

const FormItem = Form.Item

const { resetStateCustomer, putEditContact } = customerAction
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class EditContactModal extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      providerListData: [],
      radioValue: ''
    }
    this.initState = this.state
  }

  componentDidMount () {
    this.resetState()
  }

  componentWillReceiveProps (nextProps) {
    if (nextProps.editContactMessage === 'Successfully edited' &&
        !nextProps.patchEditContactError &&
        !nextProps.patchEditContactLoading) {
      this.successEdit()
    }
  }

  successEdit = () => {
    notification['success']({
      message: this.props.editContactMessage,
      description: ''
    })
    this.handleCancel()
  }

  resetState = () => {
    this.setState(this.initState)
    this.props.resetStateCustomer(['editContactMessage'])
    this.props.resetLoadingRedux(['PUT_EDIT_CONTACT'])
    this.props.resetErrorRedux(['PUT_EDIT_CONTACT'])
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  onSubmit = async e => {
    e.preventDefault()
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const {
      form,
      userid
    } = this.props
    const formValues = form.getFieldsValue()
    let payload = {
      ...formValues,
      userid: userid
    }
    this.props.putEditContact(payload)
  }

  handleCancel = () => {
    this.props.form.resetFields()
    this.props.onClosePopupForm()
    this.resetState()
  }

  onChange = e => {
    this.setState({
      radioValue: e.target.value
    })
  };

  render () {
    const { getFieldDecorator } = this.props.form
    const {
      email,
      phone,
      patchEditContactLoading,
      patchEditContactError,
      editContactMessage
    } = this.props
    return (
      <Modal
        title='Edit Customer Contact Info'
        visible={this.props.isOpen}
        onCancel={this.handleCancel}
        footer={null}
        closable
        maskClosable={false} >
        <FailedFetchAlert
          status={'error'}
          isNeedDisplay={patchEditContactError}
          message={editContactMessage}
        />
        <Form id='contact-form' onSubmit={this.onSubmit} style={{ marginTop: '10px' }}>
          <Row>
            <Col sm={6}>
              Email:
            </Col>
            <Col sm={18}>
              <FormItem>
                {getFieldDecorator('email', {
                  initialValue: email,
                  rules: [{ required: true, message: 'Please input an email address' }]
                })(<Input />)}
              </FormItem>
            </Col>
          </Row>
          <Row>
            <Col sm={6}>
              Phone number:
            </Col>
            <Col sm={18}>
              <FormItem>
                {getFieldDecorator('phone', {
                  initialValue: phone,
                  rules: [
                    { required: true, message: 'Phone number cannot be empty' },
                    {
                      pattern: /^\d{2}-\d{1,}/,
                      message:
                      'Invalid phone number, format: XX-XXXXXX/[Country code]-[Phone no]'
                    }
                  ]
                })(<Input disabled />)}
              </FormItem>
            </Col>
          </Row>
          <FormItem>
            <center>
              <Button
                className='button'
                key='cancel'
                style={{ marginTop: '20px', marginRight: '20px' }}
                onClick={this.handleCancel}
              >
                Cancel
              </Button>
              <Button
                form='contact-form'
                className='button'
                key='submit'
                type='primary'
                htmlType='submit'
                style={{ marginTop: '20px' }}
                loading={patchEditContactLoading}
              >
                Submit
              </Button>
            </center>
          </FormItem>
        </Form>
      </Modal>
    )
  }
}

const WrappedEditContactModal = Form.create()(EditContactModal)

WrappedEditContactModal.propTypes = {
  userProfile: PropTypes.object.isRequired,
  userid: PropTypes.string.isRequired,
  email: PropTypes.string,
  phone: PropTypes.string
}

WrappedEditContactModal.defaultProps = {
  userProfile: {}
}

export default connect(
  state => ({
    patchEditContactLoading: state.Loading.PUT_EDIT_CONTACT,
    patchEditContactError: state.Error.PUT_EDIT_CONTACT,
    editContactMessage: state.Customer.editContactMessage
  }),
  {
    resetStateCustomer,
    putEditContact,
    resetLoadingRedux,
    resetErrorRedux
  }
)(WrappedEditContactModal)
